            for (block.spans) |span| {
                if (span.provenance != .parsed or span.generated_diagnostic or span.flags.code or span.image != null) return null;
                if (span.role == .headword) {
                    if (!span.flags.bold or !std.mem.eql(u8, span.language, "ur") or
                        (span.kind != .text and span.kind != .link)) return null;
                    seen = seen or std.mem.trim(u8, span.text, " \t\r\n").len != 0;
                } else {
                    // The template's optional gender is body data, not POS or
                    // owner authority. Only its plain annotation/spacing may
                    // accompany the independently marked headword paragraph.
                    if (span.kind != .text or span.target.len != 0 or span.role != .normal or
                        (std.mem.trim(u8, span.text, " \t\r\n\xc2\xa0").len != 0 and
                        !std.mem.eql(u8, span.classes, "gender"))) return null;
                }
            }
            if (!seen) return null;
            headword = true;
            continue;
        }
        if (block.kind != .definition or block.depth != 1 or
            !std.mem.eql(u8, block.list_path, "#") or block.spans.len == 0) return null;
        var visible = false;
        for (block.spans) |span| {
            if (span.provenance != .parsed or span.generated_diagnostic or span.flags.code) return null;
            visible = visible or std.mem.trim(u8, span.text, " \t\r\n").len != 0;
        }
        return if (visible) "Noun" else null;
    }
    return null;
}

// The retained page explicitly says its meaning has not been entered. Keep
// that exact italic instruction (including bold edit action text) as body,
// rather than manufacture a sense from its authored list marker.
fn bulgarianMissingMeaning(block: wiki.Block) bool {
    if (block.kind != .definition or !std.mem.eql(u8, block.list_path, "#") or block.spans.len != 3) return false;
    const parts = [_][]const u8{
        "Значението на думата все още не е въведено. Можете да го добавите, както и да попълните част от останалата липсваща информация, като щракнете на ",
        "редактиране", ".",
    };
    for (block.spans, parts, 0..) |span, text, index| {
        if (span.provenance != .parsed or span.generated_diagnostic or span.self_link or span.image != null or
            span.kind != .text or span.target.len != 0 or span.role != .normal or span.flags.code or
            !span.flags.italic or span.flags.bold != (index == 1) or !std.mem.eql(u8, span.text, text)) return false;
    }
    return true;
}
fn analyzeBulgarianVerb(a: A, kind: []const u8, index: usize, etymology: ?usize, blocks: []const wiki.Block) !Lexeme {
    return analyzeProjected(a, kind, index, etymology, blocks, false, .bulgarian_request);
}

// Exact localized semantic heading plus an optional canonical positive number.
// This is an organization label, never a language or part-of-speech declaration.
fn exactNumberedHeading(title: []const u8, label: []const u8) bool {
    return exactNumberedHeadingSeparated(title, label, " ");
}

fn exactNumberedHeadingSeparated(title: []const u8, label: []const u8, separator: []const u8) bool {
    if (std.mem.eql(u8, title, label)) return true;
    if (title.len <= label.len + separator.len or !std.mem.startsWith(u8, title, label) or
        !std.mem.startsWith(u8, title[label.len..], separator)) return false;
    const number = title[label.len + separator.len ..];
    if (number[0] < '1' or number[0] > '9') return false;
    for (number[1..]) |digit| if (!std.ascii.isDigit(digit)) return false;
    return true;
}

// These H3s come from the Quechua Wiktionary's own POS templates. On
// amañachiy, -pron- also labels IPA-only material. Require a numbered definition.
// The Afrikaans participle template places its senses in a child heading.
// The following Voorbeeldsinne heading can also contain numbered lines.
fn afParticipleMeanings(sections: anytype, index: usize) bool {
    const section = sections[index];
    if (section.level != 4 or !std.mem.eql(u8, section.title, "Betekenisse") or index == 0) return false;
    const parent = sections[index - 1];
    if (parent.level != 3 or !std.mem.eql(u8, parent.title, "Deelwoord")) return false;
    return hasTopLevelNumberedGloss(section.blocks);
}

fn hasTopLevelNumberedGloss(blocks: []const wiki.Block) bool {
    for (blocks, 0..) |block, i| {
        if (block.kind == .definition and std.mem.eql(u8, block.list_path, "#") and
            !standaloneEmptyDefinition(blocks, i)) return true;
    }
    return false;
}

fn classifiedNounSection(sections: anytype, index: usize, owner: []const u8, label: []const u8) bool {
    const section = sections[index];
    const S = @TypeOf(section);
    if (!@hasField(S, "is_heading") or !@hasField(S, "title_depth") or !@hasField(S, "title_list_path")) return false;
    if (section.level != 3 or !std.mem.eql(u8, section.title, label) or !section.is_heading or
        section.title_depth != 0 or section.title_list_path.len != 0) return false;
    if (owner.len == 0 or std.mem.eql(u8, owner, "Unclassified")) return false;

    // A stored language record can include a later, unresolved H2. Only the
    // classified language's own H2 can supply the owner of this noun heading.
    var parent = index;
    while (parent != 0) {
        parent -= 1;
        const heading = sections[parent];
        if (heading.level > 2) continue;
        return heading.level == 2 and heading.is_heading and heading.title_depth == 0 and
            heading.title_list_path.len == 0 and std.mem.eql(u8, heading.title, owner) and
            hasTopLevelNumberedGloss(section.blocks);
    }
    return false;
}

fn dictionaryNounSection(section: anytype, owner: ?[]const u8, wiki_id: []const u8) bool {
    // BLK Template:noun p59/r172 emits နာမ်ႏ; Template:en-noun p3565/r8202
    // supplies the same noun class to its headword module.
    const is_noun = if (std.mem.eql(u8, wiki_id, "ptwiktionary"))
        section.level == 2 and std.mem.eql(u8, section.title, "Substantivo")
    // Amharic car p1966/r19544 explicitly labels this H3 as a noun.
    else if (std.mem.eql(u8, wiki_id, "amwiktionary"))
        section.level == 3 and std.mem.eql(u8, section.title, "ስም")
    else if (std.mem.eql(u8, wiki_id, "blkwiktionary"))
        (section.level == 3 or section.level == 4) and std.mem.eql(u8, section.title, "နာမ်ႏ")
    else
        false;
    if (!is_noun) return false;
    const language = owner orelse return false;
    if (language.len == 0 or std.mem.eql(u8, language, "Unclassified")) return false;
    if (@hasField(@TypeOf(section), "is_heading")) if (!section.is_heading) return false;
    if (@hasField(@TypeOf(section), "title_depth")) if (section.title_depth != 0) return false;
    if (@hasField(@TypeOf(section), "title_list_path")) if (section.title_list_path.len != 0) return false;
    return std.mem.eql(u8, wiki_id, "blkwiktionary") or hasTopLevelNumberedGloss(section.blocks);
}

// The Aragonese POS templates link the localized title to a grammar page.
// Resolve the lexical kind without assigning a language or moving any body text.
fn spanishDefinitionPart(section: anytype, owner: ?[]const u8, code: []const u8, wiki_id: []const u8) ?[]const u8 {
    if (!std.mem.eql(u8, wiki_id, "eswiktionary") or section.level != 3 or code.len == 0 or
        owner == null or owner.?.len == 0 or std.mem.eql(u8, owner.?, "Unclassified")) return null;
    const S = @TypeOf(section);
    if (!@hasField(S, "is_heading") or !@hasField(S, "title_depth") or !@hasField(S, "title_list_path")) return null;
    if (!section.is_heading or section.title_depth != 0 or section.title_list_path.len != 0) return null;
    const kind: []const u8 = if (std.mem.eql(u8, section.title, "Símbolo")) "Symbol" else if
        (std.mem.eql(u8, section.title, "Sustantivo") or std.mem.eql(u8, section.title, "Sustantivo inanimado")) "Noun" else return null;
    var paired = false;
    for (section.blocks, 0..) |block, index| {
        if (block.kind == .term and !numberedDefinitionDetail(section.blocks, index + 1, true, true)) return null;
        if (block.kind == .list_detail) {
            if (!numberedDefinitionDetail(section.blocks, index, true, true) or !sourceNumberedText(block)) return null;
            paired = true;
        }
    }
    return if (paired) kind else null;
}

fn aragoneseGrammarPart(section: anytype, owner: ?[]const u8, wiki_id: []const u8) ?[]const u8 {
    if (!std.mem.eql(u8, wiki_id, "anwiktionary") or section.level != 2) return null;
    const language = owner orelse return null;
    if (language.len == 0 or std.mem.eql(u8, language, "Unclassified")) return null;
    const S = @TypeOf(section);
    if (!@hasField(S, "title_spans") or !@hasField(S, "is_heading") or
        !@hasField(S, "title_depth") or !@hasField(S, "title_list_path")) return null;
    if (!section.is_heading or section.title_depth != 0 or section.title_list_path.len != 0) return null;
    const targets = [_]struct { title: []const u8, page: []const u8, kind: []const u8 }{
        .{ .title = "Sustantivo", .page = "Wiktionary:Sustantibo", .kind = "Noun" },
        .{ .title = "Sustantivo masculín", .page = "Wiktionary:Sustantibo", .kind = "Noun" },
        .{ .title = "Sustantivo femenín", .page = "Wiktionary:Sustantibo", .kind = "Noun" },
        .{ .title = "Sustantivo neutro", .page = "Wiktionary:Sustantibo", .kind = "Noun" },
        .{ .title = "Verbo transitivo", .page = "Wiktionary:Berbo", .kind = "Verb" },
        .{ .title = "Verbo intransitivo", .page = "Wiktionary:Berbo", .kind = "Verb" },
        .{ .title = "Adchectivo", .page = "Wiktionary:Adchectivo", .kind = "Adjective" },
    };
    for (targets) |grammar| {
        if (!std.mem.eql(u8, section.title, grammar.title)) continue;
        var linked = false;
        for (section.title_spans, 0..) |span, index| {
            if (span.provenance != .parsed or span.generated_diagnostic or span.flags.code or
                span.role != .normal or span.ruby != null) return null;
            // The original POS templates prefix the grammar link with this book icon.
            // Leave its media and action intact. Only the grammar link declares the part.
            if (span.image) |icon| {
                if (index != 0 or span.kind != .link or span.text.len != 0 or span.self_link or
                    span.target_fragment != null or !std.mem.eql(u8, span.target, "File:Open book 01.svg") or
                    !std.mem.eql(u8, icon.file, "Open book 01.svg") or icon.width_px != 30 or
                    icon.height_px != null or icon.alt != null or icon.map != null) return null;
                continue;
            }
            if (span.kind == .line_break or (span.kind == .text and std.mem.trim(u8, span.text, " \t\r\n").len == 0)) continue;
            if (linked or span.kind != .link or span.self_link or span.target_fragment != null or
                !std.mem.eql(u8, span.text, grammar.title) or !std.mem.eql(u8, span.target, grammar.page)) return null;
            linked = true;
        }
        return if (linked) grammar.kind else null;
    }
    return null;
}

test "Aragonese grammar links classify owned H2s without changing links or inventing senses" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Section = struct {
        title: []const u8,
        level: u8 = 2,
        is_heading: bool = true,
        title_list_path: []const u8 = "",
        title_depth: u8 = 0,
        title_spans: []const wiki.Span,
        blocks: []const wiki.Block,
    };
    const cases = [_]struct { heading: []const u8, page: []const u8, kind: []const u8, owner: []const u8, numbered: bool }{
        .{ .heading = "Sustantivo", .page = "Wiktionary:Sustantibo", .kind = "Noun", .owner = "anglés", .numbered = true },
        .{ .heading = "Sustantivo femenín", .page = "Wiktionary:Sustantibo", .kind = "Noun", .owner = "aragonés", .numbered = false },
        .{ .heading = "Verbo transitivo", .page = "Wiktionary:Berbo", .kind = "Verb", .owner = "aragonés", .numbered = false },
        .{ .heading = "Sustantivo masculín", .page = "Wiktionary:Sustantibo", .kind = "Noun", .owner = "aragonés", .numbered = true },
        .{ .heading = "Sustantivo neutro", .page = "Wiktionary:Sustantibo", .kind = "Noun", .owner = "aragonés", .numbered = true },
        .{ .heading = "Verbo intransitivo", .page = "Wiktionary:Berbo", .kind = "Verb", .owner = "aragonés", .numbered = true },
        .{ .heading = "Adchectivo", .page = "Wiktionary:Adchectivo", .kind = "Adjective", .owner = "aragonés", .numbered = true },
    };
    for (cases) |case| {
        var spans = [_]wiki.Span{ .{ .text = " " }, .{ .kind = .link, .flags = .{ .italic = true }, .text = case.heading, .target = case.page }, .{ .kind = .line_break, .text = "\n" } };
        const headword = [_]wiki.Span{.{ .text = "headword", .flags = .{ .bold = true } }};
        const gloss = [_]wiki.Span{.{ .kind = .link, .text = "meaning", .target = "original" }};
        const blocks = [_]wiki.Block{
            .{ .kind = .heading, .level = 2, .spans = &spans },
            .{ .kind = .paragraph, .spans = &headword },
            .{ .kind = .definition, .list_path = "#", .spans = &gloss },
        };
        var section: Section = .{ .title = case.heading, .title_spans = &spans, .blocks = if (case.numbered) &blocks else blocks[0..2] };
        const layout = try buildForDictionary(a, &[_]Section{section}, false, case.owner, null, "anwiktionary");
        try std.testing.expectEqual(@as(usize, 1), layout.lexemes.len);
        const lexeme = layout.lexemes[0];
        try std.testing.expectEqualStrings(case.kind, lexeme.kind);
        try std.testing.expectEqualStrings(case.owner, lexeme.language);
        try std.testing.expectEqualSlices(usize, &.{ 0, 1 }, lexeme.introduction);
        try std.testing.expectEqual(@intFromBool(case.numbered), lexeme.definitions.len);
        if (case.numbered) {
            const address = lexeme.definitions[0].block;
            try std.testing.expectEqual(@as(usize, 2), address);
            try std.testing.expectEqualStrings("original", section.blocks[address].spans[0].target);
        }
        const book: wiki.Span = .{ .kind = .link, .text = "", .target = "File:Open book 01.svg",
            .image = .{ .file = "Open book 01.svg", .width_px = 30 } };
        var decorated = [_]wiki.Span{ book, spans[0], spans[1], spans[2] };
        section.title_spans = &decorated;
        try std.testing.expectEqualStrings(case.kind, aragoneseGrammarPart(section, case.owner, "anwiktionary").?);
        section.title_spans = decorated[0..2];
        try std.testing.expect(aragoneseGrammarPart(section, case.owner, "anwiktionary") == null);
        section.title_spans = &decorated;
        decorated[0].target = "File:Other.svg";
        try std.testing.expect(aragoneseGrammarPart(section, case.owner, "anwiktionary") == null);
        decorated[0] = book;
        decorated[1] = book;
        try std.testing.expect(aragoneseGrammarPart(section, case.owner, "anwiktionary") == null);
        section.title_spans = &spans;
        try std.testing.expect(aragoneseGrammarPart(section, case.owner, "eswiktionary") == null);
        try std.testing.expect(aragoneseGrammarPart(section, null, "anwiktionary") == null);
        section.title_depth = 1;
        try std.testing.expect(aragoneseGrammarPart(section, case.owner, "anwiktionary") == null);
        section.title_depth = 0;
        spans[1].target = "Wiktionary:Unrelated";
        try std.testing.expect(aragoneseGrammarPart(section, case.owner, "anwiktionary") == null);
        spans[1].target = case.page;
        spans[1].flags.code = true;
        try std.testing.expect(aragoneseGrammarPart(section, case.owner, "anwiktionary") == null);
    }
}

fn aromanianHeadingSpan(section: anytype, owner: ?[]const u8, wiki_id: []const u8, level: u8) ?*const wiki.Span {
    if (!std.mem.eql(u8, wiki_id, "roa_rupwiktionary") or section.level != level) return null;
    const language = owner orelse return null;
    if (language.len == 0 or std.mem.eql(u8, language, "Unclassified")) return null;
    const S = @TypeOf(section);
    if (!@hasField(S, "title_spans") or !@hasField(S, "is_heading") or
        !@hasField(S, "title_depth") or !@hasField(S, "title_list_path")) return null;
    if (!section.is_heading or section.title_depth != 0 or section.title_list_path.len != 0 or section.title_spans.len != 1) return null;
    const span = &section.title_spans[0];
    if (span.provenance != .parsed or span.generated_diagnostic or span.flags.code or span.self_link or
        span.role != .normal or !std.mem.eql(u8, span.text, section.title)) return null;
    return span;
}

// The Aromanian edition's Format templates use these exact H3 labels and
// targets for entries in several languages. Only -symbol- emits plain text.
fn aromanianSectionPart(section: anytype, owner: ?[]const u8, wiki_id: []const u8) ?[]const u8 {
    const span = aromanianHeadingSpan(section, owner, wiki_id, 3) orelse return null;
    if (span.kind == .text and span.target.len == 0 and std.mem.eql(u8, span.text, "Simbol")) return "Symbol";
    if (span.kind != .link) return null;
    const Label = struct { title: []const u8, target: []const u8, part: []const u8 };
    for ([_]Label{
        .{ .title = "Sumstantivu", .target = "sumstantivu", .part = "Noun" },
        .{ .title = "Adjectiv", .target = "adjectiv", .part = "Adjective" },
        .{ .title = "Articul", .target = "articul", .part = "Article" },
        .{ .title = "Númir", .target = "număr", .part = "Numeral" },
        .{ .title = "Expresii", .target = "expresii", .part = "Phrase" },
        .{ .title = "Prepoziții", .target = "prepoziții", .part = "Preposition" },
        .{ .title = "Pronuma", .target = "pronuma", .part = "Pronoun" },
    }) |label| {
        if (std.mem.eql(u8, section.title, label.title) and std.mem.eql(u8, span.target, label.target)) return label.part;
    }
    return null;
}

fn linkedAromanianEtymologyHeading(section: anytype, owner: ?[]const u8, wiki_id: []const u8) bool {
    if (!std.mem.eql(u8, section.title, "Etimulughii")) return false;
    const heading = aromanianHeadingSpan(section, owner, wiki_id, 3) orelse return false;
    return heading.kind == .link and std.mem.eql(u8, heading.target, "etimulughii") and heading.target_fragment == null;
}

// agustu (p5584/r14483) declares a noun and supplies its headword, origin and
// translations without a numbered definition. Preserve that distinction.
fn aromanianNounWithoutGloss(sections: anytype, i: usize, page_title: ?[]const u8, owner: ?[]const u8, wiki_id: []const u8) bool {
    const title = page_title orelse return false;
    if (i != 1 or (sections.len != 3 and sections.len != 4) or title.len == 0) return false;
    const language = owner orelse return false;
    if (!std.mem.eql(u8, language, "Aromanian") and !std.mem.eql(u8, language, "Armâneaşci")) return false;
    const banner = aromanianHeadingSpan(sections[0], owner, wiki_id, 1) orelse return false;
    if (banner.kind != .link or banner.target_fragment != null or !std.mem.eql(u8, banner.text, "Armâneaşci") or
        !std.mem.eql(u8, banner.target, "armâneaşci")) return false;
    if (!linkedAromanianEtymologyHeading(sections[2], owner, wiki_id)) return false;
    if (sections.len == 4 and (sections[3].level != 3 or !std.mem.eql(u8, sections[3].title, "Pri alti limbi"))) return false;
    const blocks = sections[i].blocks;
    if (blocks.len != 2 or blocks[0].kind != .heading) return false;
    const headword = blocks[1];
    if (headword.kind != .paragraph or headword.depth != 0 or headword.list_path.len != 0 or
        !greekSynonymFlatBlock(headword) or headword.spans.len != 1) return false;
    const span = headword.spans[0];
    if (comptime @hasField(@TypeOf(span), "trail")) if (span.trail.len != 0) return false;
    return greekSynonymPlain(span) and span.flags.bold and !span.flags.italic and
        std.mem.eql(u8, span.text, title);
}

fn postposedAromanianEtymology(sections: anytype, lexeme: Lexeme, owner: ?[]const u8, wiki_id: []const u8) ?usize {
    const i = lexeme.section + 1;
    if (i >= sections.len or lexeme.etymology != null or sections[lexeme.section].level != 3) return null;
    const section = sections[i];
    if (!linkedAromanianEtymologyHeading(section, owner, wiki_id)) return null;

    // Format:-ety- (3602/15630) supplies the prompt. Require content beyond it.
    if (section.blocks.len < 2 or section.blocks[0].kind != .heading or section.blocks[1].kind != .paragraph) return null;
    const spans = section.blocks[1].spans;
    const prompt = "Dit ţi limbâ v'ini zborlu";
    if (section.blocks[1].depth != 0 or section.blocks[1].list_path.len != 0 or spans.len == 0) return null;
    const first = spans[0];
    if (first.kind != .text or first.provenance != .parsed or first.flags.code or
        !std.mem.startsWith(u8, first.text, prompt)) return null;
    const tail = first.text[prompt.len..];
    if (tail.len != 0 and !std.ascii.isWhitespace(tail[0])) return null;
    for (sections, 0..) |other_section, n| {
        if (n != i and std.mem.eql(u8, other_section.title, section.title)) return null;
    }
    var has_content = false;
    for (spans, 0..) |span, n| {
        if (span.generated_diagnostic) return null;
        const text = if (n == 0) span.text[prompt.len..] else span.text;
        if (std.mem.trim(u8, text, " \t\r\n.,:").len != 0) has_content = true;
    }
    return if (has_content) i else null;
}

// The entry limbã uses :[1], :[2] in place of ordinary # definitions. Keep
// the original indentation, labels and links; only index their block addresses.
fn aromanianIndentedSenses(blocks: []const wiki.Block) ?MarkedParagraphPart {
    var first: usize = 0;
    while (first < blocks.len and (blocks[first].kind == .heading or blocks[first].kind == .blank)) first += 1;
    if (first >= blocks.len or blocks[first].kind != .paragraph or blocks[first].spans.len == 0) return null;
    const headword = blocks[first].spans[0];
    if (!icelandicPlain(headword) or !headword.flags.bold or std.mem.trim(u8, headword.text, " \t").len == 0) return null;
    first += 1;
    while (first < blocks.len and blocks[first].kind == .blank) first += 1;
    var expected: usize = 1;
    for (blocks[first..]) |block| {
        if (block.kind == .blank) continue;
        if (block.depth != 1 or !bracketNumberedMeaning(block)) return null;
        const marker = block.spans[0].text;
        const close = std.mem.indexOfScalar(u8, marker, ']') orelse return null;
        const number = std.fmt.parseUnsigned(usize, marker[1..close], 10) catch return null;
        if (number != expected) return null;
        expected += 1;
    }
    return if (expected > 1) .{ .kind = "Noun", .first = first, .end = blocks.len, .bracket_numbered = true } else null;
}

test "Aromanian dictionary linked noun headings preserve ordinary and bracketed glosses" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const encoder = @import("blob_encoder");
    const T = encoder.presentation_types;
    const Section = struct {
        title: []const u8 = "Sumstantivu",
        level: u8 = 3,
        is_heading: bool = true,
        title_list_path: []const u8 = "",
        title_depth: u8 = 0,
        title_spans: []const wiki.Span,
        blocks: []const wiki.Block,
    };
    const cases = [_]struct { title: []const u8, language: []const u8, code: []const u8, body: []const u8, targets: []const []const u8 }{
        .{ .title = "water", .language = "Inglezaşci", .code = "en", .body = "'''water'''\n# [[apã]]", .targets = &.{"apã"} },
        .{ .title = "limbã", .language = "Armâneaşci", .code = "roa-rup", .body = "'''limbã''' ''f'' (pl. '''[[limbe]]''')\n:[1] [[organ|Organ]]\n:[2] [[system|System]] ti comunicatsia anamisa di prãvdzãle cama analtsã shi ominjlji.", .targets = &.{ "organ", "system" } },
    };
    for (cases) |case| {
        var renderer: wiki.Renderer = .{ .a = a, .context = .{ .title = case.title } };
        const heading = (try renderer.renderBody("[[sumstantivu|Sumstantivu]]"))[0].spans;
        const body = try renderer.renderBody(case.body);
        const blocks = try a.alloc(wiki.Block, body.len + 1);
        blocks[0] = .{ .kind = .heading, .level = 3, .spans = heading };
        @memcpy(blocks[1..], body);
        const sections = [_]Section{.{ .title_spans = heading, .blocks = blocks }};
        const layout = try buildForDictionary(a, &sections, false, case.language, null, "roa_rupwiktionary");
        try std.testing.expectEqual(@as(usize, 1), layout.lexemes.len);
        const noun = layout.lexemes[0];
        try std.testing.expectEqualStrings("Noun", noun.kind);
        try std.testing.expectEqualStrings(case.language, noun.language);
        try std.testing.expectEqual(case.targets.len, noun.definitions.len);
        try std.testing.expectEqualSlices(usize, &.{ 0, 1 }, noun.introduction);
        const encoded = try encoder.presentation_codec.encodeBuildAlloc(a, @as([]const wiki.Span, &.{}), &sections,
            layout, @as([]const T.Reference, &.{}), @as([]const T.Media, &.{}));
        const decoded = try encoder.presentation_codec.decodeAlloc(a, encoded, case.title, .language, .{ .heading = case.language, .code = case.code });
        const stored = decoded.entry.organization.lexemes[0];
        for (case.targets, stored.definitions, 0..) |target, sense, i| {
            try std.testing.expectEqual(i + 2, sense.block);
            const block = decoded.entry.sections[0].blocks[sense.block];
            try std.testing.expectEqualStrings(if (case.targets.len == 1) "#" else ":", block.list_path);
            var found = false;
            for (block.spans) |span| {
                if (span.kind == .link and std.mem.eql(u8, span.target, target)) found = true;
            }
            try std.testing.expect(found);
            if (case.targets.len == 2) try std.testing.expectEqualStrings(if (i == 0) "[1] " else "[2] ", block.spans[0].text);
        }
        try std.testing.expectEqualSlices(u8, encoded, try encoder.presentation_codec.encodeAlloc(a, decoded));
        try std.testing.expectEqual(@as(usize, 0), (try buildForDictionary(a, &sections, true, null, null, "roa_rupwiktionary")).lexemes.len);
        try std.testing.expectEqual(@as(usize, 0), (try buildForDictionary(a, &sections, false, case.language, null, "otherwiki")).lexemes.len);
        const wrong_heading = try a.dupe(wiki.Span, heading);
        wrong_heading[0].target = "another page";
        const wrong = [_]Section{.{ .blocks = blocks, .title_spans = wrong_heading }};
        try std.testing.expectEqual(@as(usize, 0), (try buildForDictionary(a, &wrong, false, case.language, null, "roa_rupwiktionary")).lexemes.len);
        if (case.targets.len == 2) {
            const duplicate = try a.dupe(wiki.Block, blocks);
            duplicate[3] = blocks[2];
            try std.testing.expect(aromanianIndentedSenses(duplicate) == null);
        }
    }
}

test "Aromanian limbã attaches the following sourced etymology to its noun without moving its body" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const encoder = @import("blob_encoder");
    const T = encoder.presentation_types;
    const Section = struct {
        title: []const u8,
        level: u8 = 3,
        is_heading: bool = true,
        title_list_path: []const u8 = "",
        title_depth: u8 = 0,
        title_spans: []const wiki.Span,
        blocks: []const wiki.Block,
    };
    var renderer: wiki.Renderer = .{ .a = a, .context = .{ .title = "limbã" } };
    const noun = (try renderer.renderBody("[[sumstantivu|Sumstantivu]]"))[0].spans;
    const ety = (try renderer.renderBody("[[etimulughii|Etimulughii]]"))[0].spans;
    // Ordinary expanded p3530/r14967, including Format:-ety- p3602/r15630.
    const body = try renderer.renderBody("'''limbã''' ''f'' (pl. '''[[limbe]]''')\n:[1] [[organ|Organ]]\n:[2] [[system|System]] ti comunicatsia anamisa di prãvdzãle cama analtsã shi ominjlji.");
    const lexical = try a.alloc(wiki.Block, 1 + body.len);
    lexical[0] = .{ .kind = .heading, .level = 3, .spans = noun };
    @memcpy(lexical[1..], body);
    const prompt = "Dit ţi limbâ v'ini zborlu";
    const origin = [_]wiki.Block{
        .{ .kind = .heading, .level = 3, .spans = ety },
        (try renderer.renderBody(prompt ++ " latinã ''[[lingua]]''"))[0],
    };
    const sections = [_]Section{
        .{ .title = "Sumstantivu", .title_spans = noun, .blocks = lexical },
        .{ .title = "Etimulughii", .title_spans = ety, .blocks = &origin },
    };
    const layout = try buildForDictionary(a, &sections, false, "Armâneaşci", null, "roa_rupwiktionary");
    try std.testing.expectEqual(@as(usize, 1), layout.lexemes.len);
    try std.testing.expectEqual(@as(?usize, 1), layout.lexemes[0].etymology);
    const encoded = try encoder.presentation_codec.encodeBuildAlloc(a, @as([]const wiki.Span, &.{}), &sections, layout, @as([]const T.Reference, &.{}), @as([]const T.Media, &.{}));
    const stored = try encoder.presentation_codec.decodeAlloc(a, encoded, "limbã", .language, .{ .heading = "Armâneaşci", .code = "roa-rup" });
    const noun_record = stored.entry.organization.lexemes[0];
    try std.testing.expectEqualStrings("Noun", noun_record.kind);
    try std.testing.expectEqual(@as(?usize, 1), noun_record.etymology);
    try std.testing.expectEqualSlices(usize, &.{1}, stored.entry.organization.other_sections);
    try std.testing.expectEqual(@as(usize, 2), noun_record.definitions.len);
    for (noun_record.definitions, [_][]const u8{ "organ", "system" }, 2..) |sense, target, i| {
        try std.testing.expectEqual(i, sense.block);
        try std.testing.expectEqualStrings(target, stored.entry.sections[0].blocks[sense.block].spans[1].target);
    }
    const etymons = stored.entry.sections[noun_record.etymology.?].blocks[1].spans;
    try std.testing.expectEqual(@as(usize, 2), etymons.len);
    try std.testing.expectEqualStrings(prompt ++ " latinã ", etymons[0].text);
    try std.testing.expect(etymons[1].kind == .link and etymons[1].italic);
    try std.testing.expectEqualStrings("lingua", etymons[1].target);
    try std.testing.expectEqualStrings("lingua", etymons[1].text);
    try std.testing.expectEqualSlices(u8, encoded, try encoder.presentation_codec.encodeAlloc(a, stored));

    var unassigned = layout.lexemes[0];
    unassigned.etymology = null;
    for ([_][]const u8{ prompt, prompt ++ ".", prompt ++ "x latinã" }) |text| {
        var bad_body = origin;
        bad_body[1] = (try renderer.renderBody(text))[0];
        var example = sections;
        example[1].blocks = &bad_body;
        try std.testing.expect(postposedAromanianEtymology(&example, unassigned, "Armâneaşci", "roa_rupwiktionary") == null);
    }
    for ([_][]const u8{ "Etimulughii", "[[different|Etimulughii]]", "[[etimulughii#foreign|Etimulughii]]" }) |markup| {
        var example = sections;
        example[1].title_spans = (try renderer.renderBody(markup))[0].spans;
        try std.testing.expect(postposedAromanianEtymology(&example, unassigned, "Armâneaşci", "roa_rupwiktionary") == null);
    }
    try std.testing.expect(postposedAromanianEtymology(&sections, unassigned, null, "roa_rupwiktionary") == null);
    try std.testing.expect(postposedAromanianEtymology(&sections, unassigned, "Armâneaşci", "otherwiki") == null);
    try std.testing.expect(postposedAromanianEtymology(&sections, layout.lexemes[0], "Armâneaşci", "roa_rupwiktionary") == null);
    const duplicated = [_]Section{ sections[0], sections[1], sections[1] };
    const dup = try buildForDictionary(a, &duplicated, false, "Armâneaşci", null, "roa_rupwiktionary");
    try std.testing.expect(dup.lexemes[0].etymology == null);
    const ambiguous = [_]Section{ sections[0], sections[1], sections[0] };
    const many = try buildForDictionary(a, &ambiguous, false, "Armâneaşci", null, "roa_rupwiktionary");
    try std.testing.expectEqual(@as(usize, 2), many.lexemes.len);
    for (many.lexemes) |lexeme| try std.testing.expect(lexeme.etymology == null);
}

test "Aromanian agustu retains its source-declared noun and etymology without inventing a definition" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const encoder = @import("blob_encoder");
    const T = encoder.presentation_types;
    const Section = struct {
        title: []const u8,
        level: u8,
        is_heading: bool = true,
        title_list_path: []const u8 = "",
        title_depth: u8 = 0,
        title_spans: []const wiki.Span,
        blocks: []const wiki.Block,

        fn make(r: *wiki.Renderer, level: u8, label: []const u8, heading: []const u8, source: []const u8) !@This() {
            const title_spans = (try r.renderBody(heading))[0].spans;
            const body = try r.renderBody(source);
            const blocks = try r.a.alloc(wiki.Block, body.len + 1);
            blocks[0] = .{ .kind = .heading, .level = level, .spans = title_spans };
            @memcpy(blocks[1..], body);
            return .{ .title = label, .level = level, .title_spans = title_spans, .blocks = blocks };
        }
    };
    var renderer: wiki.Renderer = .{ .a = a, .context = .{ .title = "agustu" } };
    const sections = [_]Section{
        try Section.make(&renderer, 1, "Armâneaşci", "[[armâneaşci|Armâneaşci]]", ""),
        try Section.make(&renderer, 3, "Sumstantivu", "[[sumstantivu|Sumstantivu]]", "'''agustu'''"),
        try Section.make(&renderer, 3, "Etimulughii", "[[etimulughii|Etimulughii]]", "Dit ţi limbâ v'ini zborlu latinâ '''[[augustus (mensis)|augustus]]'''."),
        try Section.make(&renderer, 3, "Pri alti limbi", "Pri alti limbi", ":*[[italianeaşci|Italianeaşci]]: [[agosto]]\n:*[[ispanjolã|Ispanjolã]]: [[augusto]]\n:*[[frânţeaşci|Frânţeaşci]]: [[août]]\n:*[[inglezaşci|Inglezaşci]]: [[august]]\n:*[[rumãneaşci|Rumãneaşci]]: [[august]]"),
    };
    const layout = try buildForEntry(a, &sections, false, "Aromanian", null, "roa_rupwiktionary", &.{}, "agustu");
    try std.testing.expectEqual(@as(usize, 1), layout.lexemes.len);
    const bytes = try encoder.presentation_codec.encodeBuildAlloc(a, @as([]const wiki.Span, &.{}), &sections, layout, @as([]const T.Reference, &.{}), @as([]const T.Media, &.{}));
    const stored = try encoder.presentation_codec.decodeAlloc(a, bytes, "agustu", .language, .{ .heading = "Aromanian", .code = "roa-rup" });
    const noun = stored.entry.organization.lexemes[0];
    try std.testing.expectEqualStrings("Noun", noun.kind);
    try std.testing.expectEqualStrings("Aromanian", noun.language);
    try std.testing.expectEqual(@as(usize, 1), noun.section);
    try std.testing.expectEqual(@as(?usize, 2), noun.etymology);
    try std.testing.expectEqual(@as(usize, 0), noun.definitions.len);
    try std.testing.expectEqualSlices(usize, &.{ 0, 1 }, noun.introduction);
    try std.testing.expectEqualSlices(usize, &.{ 0, 2, 3 }, stored.entry.organization.other_sections);
    const word = stored.entry.sections[noun.section].blocks[1].spans[0];
    try std.testing.expect(word.bold and std.mem.eql(u8, word.text, "agustu"));
    const etymon = stored.entry.sections[noun.etymology.?].blocks[1].spans[1];
    try std.testing.expect(etymon.kind == .link and etymon.bold);
    try std.testing.expectEqualStrings("augustus", etymon.text);
    try std.testing.expectEqualStrings("augustus (mensis)", etymon.target);
    const translations = stored.entry.sections[3].blocks[1..];
    try std.testing.expectEqual(@as(usize, 5), translations.len);
    for (translations, [_][]const u8{ "agosto", "augusto", "août", "august", "august" }) |block, target| {
        try std.testing.expectEqualStrings(target, block.spans[2].target);
    }
    try std.testing.expectEqualSlices(u8, bytes, try encoder.presentation_codec.encodeAlloc(a, stored));
    for ([_]?[]const u8{ null, "different title" }) |title| {
        const wrong = try buildForEntry(a, &sections, false, "Aromanian", null, "roa_rupwiktionary", &.{}, title);
        try std.testing.expectEqual(@as(usize, 0), wrong.lexemes.len);
    }
    const unknown = try buildForEntry(a, &sections, true, null, null, "roa_rupwiktionary", &.{}, "agustu");
    try std.testing.expectEqual(@as(usize, 0), unknown.lexemes.len);
    const foreign = try buildForEntry(a, &sections, false, "Aromanian", null, "otherwiki", &.{}, "agustu");
    try std.testing.expectEqual(@as(usize, 0), foreign.lexemes.len);
    var different = sections;
    different[3] = sections[1];
    const competing = try buildForEntry(a, &different, false, "Aromanian", null, "roa_rupwiktionary", &.{}, "agustu");
    try std.testing.expectEqual(@as(usize, 0), competing.lexemes.len);
    different = sections;
    different[1] = try Section.make(&renderer, 3, "Sumstantivu", "[[sumstantivu|Sumstantivu]]", "agustu");
    const prose = try buildForEntry(a, &different, false, "Aromanian", null, "roa_rupwiktionary", &.{}, "agustu");
    try std.testing.expectEqual(@as(usize, 0), prose.lexemes.len);
}

test "Aromanian dictionary indexes seven source-declared lexical sections under their supplied language" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const encoder = @import("blob_encoder");
    const T = encoder.presentation_types;
    const Section = struct {
        title: []const u8,
        level: u8 = 3,
        is_heading: bool = true,
        title_list_path: []const u8 = "",
        title_depth: u8 = 0,
        title_spans: []const wiki.Span,
        blocks: []const wiki.Block,
    };
    // Original edition's POS headings and lexical sections. The symbol's
    // following synonyms and the second language on basta are separate sections.
    const Case = struct { title: []const u8, code: []const u8, heading: []const u8, body: []const u8, part: []const u8, target: []const u8 };
    const cases = [_]Case{
        .{ .title = "acru", .code = "ro", .heading = "[[adjectiv|Adjectiv]]", .body = "'''acru'''\n# [[agru]]", .part = "Adjective", .target = "agru" },
        .{ .title = "an", .code = "en", .heading = "[[articul|Articul]]", .body = "'''an'''\n# [['nâ]]", .part = "Article", .target = "'nâ" },
        .{ .title = "bat", .code = "eu", .heading = "[[număr|Númir]]", .body = "'''bat'''\n# [[un]]", .part = "Numeral", .target = "un" },
        .{ .title = "basta", .code = "es", .heading = "[[expresii|Expresii]]", .body = "'''basta'''!\n# [[duri]]!", .part = "Phrase", .target = "duri" },
        .{ .title = "dans", .code = "fr", .heading = "[[prepoziții|Prepoziții]]", .body = "'''dans'''\n# [['n]]", .part = "Preposition", .target = "'n" },
        .{ .title = "I", .code = "en", .heading = "[[pronuma|Pronuma]]", .body = "'''I'''\n# [[io]]", .part = "Pronoun", .target = "io" },
        .{ .title = "⯉", .code = "mul", .heading = "Simbol", .body = "# (astronomie) planeta [[Neptun]]", .part = "Symbol", .target = "Neptun" },
    };
    for (cases) |case| {
        var renderer: wiki.Renderer = .{ .a = a, .context = .{ .title = case.title } };
        const heading = (try renderer.renderBody(case.heading))[0].spans;
        const body = try renderer.renderBody(case.body);
        const sections = [_]Section{.{ .title = heading[0].text, .title_spans = heading, .blocks = body }};
        const layout = try buildForDictionary(a, &sections, false, case.code, null, "roa_rupwiktionary");
        try std.testing.expectEqual(@as(usize, 1), layout.lexemes.len);
        const encoded = try encoder.presentation_codec.encodeBuildAlloc(a, @as([]const wiki.Span, &.{}), &sections,
            layout, @as([]const T.Reference, &.{}), @as([]const T.Media, &.{}));
        const stored = try encoder.presentation_codec.decodeAlloc(a, encoded, case.title, .language, .{ .heading = case.code, .code = case.code });
        const lexeme = stored.entry.organization.lexemes[0];
        try std.testing.expectEqualStrings(case.code, lexeme.language);
        try std.testing.expectEqualStrings(case.part, lexeme.kind);
        try std.testing.expectEqual(@as(usize, 1), lexeme.definitions.len);
        const block = stored.entry.sections[0].blocks[lexeme.definitions[0].block];
        try std.testing.expectEqualStrings("#", block.list_path);
        var targets: usize = 0;
        for (block.spans) |span| if (span.kind == .link) {
            try std.testing.expectEqualStrings(case.target, span.target);
            targets += 1;
        };
        try std.testing.expectEqual(@as(usize, 1), targets);
        try std.testing.expectEqualSlices(u8, encoded, try encoder.presentation_codec.encodeAlloc(a, stored));
        try std.testing.expect(aromanianSectionPart(sections[0], null, "roa_rupwiktionary") == null);
        try std.testing.expect(aromanianSectionPart(sections[0], case.code, "otherwiki") == null);
        var wrong = sections[0];
        const spans = try a.dupe(wiki.Span, heading);
        spans[0].target = "unrelated";
        wrong.title_spans = spans;
        try std.testing.expect(aromanianSectionPart(wrong, case.code, "roa_rupwiktionary") == null);
    }
}

fn amharicNounGloss(sections: anytype, index: usize, owner: ?[]const u8, code: []const u8, wiki_id: []const u8) bool {
    if (index < 2 or !std.mem.eql(u8, wiki_id, "amwiktionary") or !std.mem.eql(u8, code, "am") or
        !std.mem.eql(u8, owner orelse "", "አማርኛ")) return false;
    if (!std.mem.eql(u8, sections[index].title, "ገለፃ/ትርጉም")) return false;
    const first = index - 2;
    const labels = [_][]const u8{ "ቋንቋ", "የንግግር ክፍል", "ገለፃ/ትርጉም" };
    const values = [_][]const u8{ "አማርኛ", "ስም" };
    for (sections, 0..) |section, i| {
        if (i < first or i > index) {
            for (labels) |label| if (std.mem.eql(u8, section.title, label)) return false;
            continue;
        }
        if (section.level != 3 or !std.mem.eql(u8, section.title, labels[i - first]) or !czechMeaningHeading(section)) return false;
        if (i == index) continue;
        if (section.blocks.len != 1) return false;
        const field = section.blocks[0];
        if (field.kind != .list_item or field.depth != 1 or !std.mem.eql(u8, field.list_path, "*") or
            field.spans.len != 1 or field.table != null or field.feature != null or field.container != null or field.flow != null) return false;
        const value = field.spans[0];
        if (value.kind != .text or value.target.len != 0 or !teluguGrammarPlainSpan(value) or
            !std.mem.eql(u8, value.text, values[i - first])) return false;
    }
    for (sections[index].blocks) |block| {
        if (block.kind == .definition and block.depth == 1 and std.mem.eql(u8, block.list_path, "#") and sourceNumberedText(block)) return true;
    }
    return false;
}

// The Gun dictionary defines the two noun labels on pages 1272 and 1855,
// and the verb label on page 858, with English and French translations.
fn gunDefinitionPart(section: anytype) ?[]const u8 {
    if (section.level != 2) return null;
    const S = @TypeOf(section);
    if (!@hasField(S, "is_heading") or !@hasField(S, "title_depth") or !@hasField(S, "title_list_path")) return null;
    if (!section.is_heading or section.title_depth != 0 or section.title_list_path.len != 0) return null;
    const kind: []const u8 = if (std.mem.eql(u8, section.title, "Yinkọgbe") or std.mem.eql(u8, section.title, "Nyǐkɔgbe"))
        "Noun"
    else if (std.mem.eql(u8, section.title, "Nuwagbe"))
        "Verb"
    else
        return null;
    return if (hasTopLevelNumberedGloss(section.blocks)) kind else null;
}

fn quechuaDefinitionPart(section: anytype) ?[]const u8 {
    if (section.level != 3) return null;
    const headings = .{
        .{ "Suti", "Noun" },
        .{ "Simichaq", "Verb" },
        .{ "Sutip Rampaqnin", "Adjective" },
        .{ "Sutip Rantin", "Pronoun" },
        .{ "Simichaqpa K'askaqnin", "Adverb" },
        .{ "Huchha Simi", "Numeral" },
        .{ "Mayñiq Simi", "Preposition" },
    };
    inline for (headings) |heading| {
        if (std.mem.eql(u8, section.title, heading[0])) {
            return if (hasTopLevelNumberedGloss(section.blocks)) heading[1] else null;
        }
    }
    return null;
}

pub fn buildForDictionary(a: A, sections: anytype, unclassified: bool, owner: ?[]const u8, source_lexeme: ?SourceLexeme, wiki_id: []const u8) !Layout {
    return buildForDictionaryWithSourceNumberedLexemes(a, sections, unclassified, owner, source_lexeme, wiki_id, &.{});
}

pub fn buildForDictionaryWithSourceNumberedLexemes(a: A, sections: anytype, unclassified: bool, owner: ?[]const u8, source_lexeme: ?SourceLexeme, wiki_id: []const u8, numbered_proofs: []const SourceNumberedLexeme) !Layout {
    return buildForEntry(a, sections, unclassified, owner, source_lexeme, wiki_id, numbered_proofs, null);
}

pub fn buildForEntry(a: A, sections: anytype, unclassified: bool, owner: ?[]const u8, source_lexeme: ?SourceLexeme, wiki_id: []const u8, numbered_proofs: []const SourceNumberedLexeme, page_title: ?[]const u8) !Layout {
    return buildForEntryWithClassifiedCode(a, sections, unclassified, owner, "", source_lexeme, wiki_id, numbered_proofs, page_title);
}

pub fn buildForEntryWithClassifiedCode(a: A, sections: anytype, unclassified: bool, owner: ?[]const u8, owner_code: []const u8, source_lexeme: ?SourceLexeme, wiki_id: []const u8, numbered_proofs: []const SourceNumberedLexeme, page_title: ?[]const u8) !Layout {
    const quechua = std.mem.eql(u8, wiki_id, "quwiktionary");
    // Manx templates Clowan:-noun- (2046/6670) and Clowan:-ennym- (2249/5343)
    // both emit Ennymockle for nouns, including words in other languages.
    const owned_noun_label: ?[]const u8 = if (unclassified or owner == null or owner_code.len == 0) null else if (std.mem.eql(u8, wiki_id, "mlwiktionary")) "നാമം" else if (std.mem.eql(u8, wiki_id, "gvwiktionary")) "Ennymockle" else null;
    const af_dictionary = std.mem.eql(u8, wiki_id, "afwiktionary");
