    const support = try renderer.renderBody("* [[support]]\n");
    for ([_][]const u8{ "Tegusõnavorm", "Tegusõnavorm (1)", "Tegusõnavorm (24)", "Morfeem" }) |heading| {
        const sections = [_]Section{
            .{ .title = "French", .level = 2 },
