    const sections = [_]Section{ .{ .title = "English", .level = 1 }, .{ .title = "Substantivo feminino", .level = 3, .blocks = &body }, .{ .title = "Observacións", .level = 4, .blocks = &support }, .{ .title = "Termos relacionados", .level = 4 } };
