            else => unreachable,
        }
        try std.testing.expect(ownedSindhiNounPart(changed, "Sindhi") == null);
    }
    try std.testing.expectEqualStrings("Noun", partOfSpeech("Noun") orelse return error.TestUnexpectedResult);
}


