test "actual Chinese estoire keeps the complete Reader while linking both authored etymologies" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const encoder = @import("blob_encoder");
    const T = encoder.presentation_types;
    const bytes = @embedFile("testdata/zh-estoire-etymology/reader.json");
    const raw = @embedFile("testdata/zh-estoire-etymology/raw.wikitext");
    const expanded = @embedFile("testdata/zh-estoire-etymology/expanded.wikitext");
    for ([_]struct { bytes: []const u8, hash: []const u8 }{
        .{ .bytes = bytes, .hash = "ccc129ac9f8412da13267fb1378640397d0bc66c60496cca85c46685acf867af" },
        .{ .bytes = raw, .hash = "19a98aad649fe37d6a7ac33042cc20499c2396765366f2025872170bbab736e3" },
        .{ .bytes = expanded, .hash = "48bbadcde64d36556b4ccdb08fba228b77ba474e93368f610fdd69934875893c" },
    }) |fixture| {
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(fixture.bytes, &digest, .{});
        try std.testing.expectEqualStrings(fixture.hash, &std.fmt.bytesToHex(digest, .lower));
    }
    // Both headings are authored directly, not inferred from the word's language.
    // The original fro-noun/head templates independently explain the two nouns.
    for ([_][]const u8{ "===词源1===", "===词源2===", "{{fro-noun|f}}", "{{head|fro|名词}}", "# [[历史]]", "# [[故事]]", "# {{alt form|fro|estoile}}" }) |piece|
        try std.testing.expect(std.mem.indexOf(u8, raw, piece) != null);
    for ([_][]const u8{ "===词源1===", "===词源2===", "entity=Q397 site=zhwiki", "entity=Q35497 site=zhwiki", "-{[[:στολή#古希臘語|-{στολή}-]]}-" }) |piece|
        try std.testing.expect(std.mem.indexOf(u8, expanded, piece) != null);
    const typed = try std.json.parseFromSlice(struct { entries: []const T.Entry }, a, bytes, .{ .ignore_unknown_fields = true });
    try std.testing.expectEqual(@as(usize, 1), typed.value.entries.len);
    const before = typed.value.entries[0];
    try std.testing.expectEqualStrings("estoire", before.title);
    try std.testing.expectEqualStrings("古法語", before.language.?);
    try std.testing.expectEqualStrings("fro", before.language_code);
    try std.testing.expectEqual(@as(usize, 8), before.sections.len);
    try std.testing.expectEqualStrings("词源1", before.sections[1].title);
    try std.testing.expectEqualStrings("词源2", before.sections[5].title);
    const sections = try SerbianMeaningTest.projected(a, before);
    const computed = try buildOwned(a, sections, before.language.?);
    const organization = try std.json.parseFromSlice(T.Layout, a, try std.json.Stringify.valueAlloc(a, computed, .{}), .{});
    var expected: T.Stored = .{ .entry = before };
    const lexemes = try a.dupe(T.Lexeme, before.organization.lexemes);
    expected.entry.organization.lexemes = lexemes;
    try std.testing.expectEqual(@as(usize, 2), lexemes.len);
    for (lexemes, [_]usize{ 1, 5 }, [_]usize{ 3, 6 }, [_]usize{ 2, 1 }) |*noun, origin, section, count| {
        try std.testing.expect(noun.etymology == null);
        try std.testing.expectEqualStrings("Noun", noun.kind);
        try std.testing.expectEqualStrings("古法語", noun.language);
        try std.testing.expectEqual(section, noun.section);
        try std.testing.expectEqual(count, noun.definitions.len);
        for (noun.definitions, 1..) |sense, index| try std.testing.expectEqual(index, sense.block);
        noun.etymology = origin;
    }
    try std.testing.expectEqualDeep(expected.entry.organization, organization.value);
    var actual: T.Stored = .{ .entry = before };
    actual.entry.organization = organization.value;
    try std.testing.expectEqualDeep(expected, actual);
    const encoded = try encoder.presentation_codec.encodeAlloc(a, actual);
    const decoded = try encoder.presentation_codec.decodeAlloc(a, encoded, before.title, before.kind, .{ .heading = before.language.?, .code = before.language_code });
    try std.testing.expectEqualDeep(expected, decoded);
    try std.testing.expectEqualSlices(u8, encoded, try encoder.presentation_codec.encodeAlloc(a, decoded));
    var restored = decoded;
    restored.entry.organization = before.organization;
    try std.testing.expectEqualDeep(T.Stored{ .entry = before }, restored);
    try std.testing.expectEqualSlices(u8, try encoder.presentation_codec.encodeAlloc(a, .{ .entry = before }), try encoder.presentation_codec.encodeAlloc(a, restored));
    var span_count: usize = 0;
    var action_count: usize = 0;
    var greek_count: usize = 0;
    var source_errors: usize = 0;
    for (decoded.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
        span_count += 1;
        if (span.target.len != 0) action_count += 1;
        if (std.mem.startsWith(u8, span.text, "Lua error in Module:Etymology/templates:")) source_errors += 1;
        if (std.mem.eql(u8, span.target, "στολή#古希臘語")) {
            try std.testing.expectEqualStrings("στολή", span.text);
            try std.testing.expectEqualStrings("grc", span.language);
            greek_count += 1;
        }
    };
    for (decoded.entry.references) |reference| for (reference.spans) |span| {
        span_count += 1;
        if (span.target.len != 0) action_count += 1;
    };
    try std.testing.expectEqual(@as(usize, 72), span_count);
    try std.testing.expectEqual(@as(usize, 21), action_count);
    try std.testing.expectEqual(@as(usize, 1), greek_count);
    try std.testing.expectEqual(@as(usize, 2), source_errors);
    try std.testing.expectEqual(@as(usize, 1), decoded.entry.references.len);
    try std.testing.expectEqualDeep(before.references, decoded.entry.references);
}

test "Chinese compact etymology numbers require exact headings and preserve ordinary text and owner boundaries" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{ "词源", "词源1", "词源2", "词源12" }) |title|
        try std.testing.expect(exactNumberedHeadingSeparated(title, "词源", ""));
    for ([_][]const u8{ "词源0", "词源01", "词源-1", "词源1a", "词源 1", "词源1 ", "词源说明", "关于词源1", "<nowiki>词源1</nowiki>" }) |title|
        try std.testing.expect(!exactNumberedHeadingSeparated(title, "词源", ""));
    try std.testing.expect(partOfSpeech("词源1") == null);
    const Section = struct { title: []const u8, level: u8, blocks: []const wiki.Block = &.{} };
    var renderer: wiki.Renderer = .{ .a = a, .context = .{} };
    const ordinary = try renderer.renderBody("词源1\n<nowiki>===词源2===</nowiki>\n<pre>===词源1===</pre>\n");
    const body = try renderer.renderBody("'''word'''\n# [[meaning|meaning]]\n");
    const text_sections = [_]Section{ .{ .title = "Notes", .level = 3, .blocks = ordinary }, .{ .title = "名词", .level = 4, .blocks = body } };
    const text_layout = try buildOwned(a, &text_sections, "Independent owner");
    try std.testing.expectEqual(@as(usize, 1), text_layout.lexemes.len);
    try std.testing.expect(text_layout.lexemes[0].etymology == null);
    for ([_][]const u8{ "词源说明", "词源0", "词源01", "词源1a", "关于词源1" }) |title| {
        const unproved = [_]Section{ .{ .title = title, .level = 3 }, .{ .title = "名词", .level = 4, .blocks = body } };
        const layout = try buildOwned(a, &unproved, "Independent owner");
        try std.testing.expectEqual(@as(usize, 1), layout.lexemes.len);
        try std.testing.expect(layout.lexemes[0].etymology == null);
    }
    const regions = [_]Section{
        .{ .title = "First owner", .level = 2 }, .{ .title = "词源1", .level = 3 }, .{ .title = "名词", .level = 4, .blocks = body },
        .{ .title = "词源2", .level = 3 }, .{ .title = "名词", .level = 4, .blocks = body },
        .{ .title = "Second owner", .level = 2 }, .{ .title = "名词", .level = 3, .blocks = body },
    };
    const layout = try buildOwned(a, &regions, "Independent owner");
    try std.testing.expectEqual(@as(usize, 3), layout.lexemes.len);
    for (layout.lexemes, [_]?usize{ 1, 3, null }) |noun, origin| {
        try std.testing.expectEqual(origin, noun.etymology);
        try std.testing.expectEqualStrings("Independent owner", noun.language);
    }
    const support = [_]Section{ .{ .title = "词源1", .level = 3 }, .{ .title = "Support", .level = 4, .blocks = body } };
    try std.testing.expectEqual(@as(usize, 0), (try buildOwned(a, &support, "Independent owner")).lexemes.len);
}

const AragoneseDecimalTest = struct {
    const Section = struct {
        title: []const u8, level: u8, blocks: []const wiki.Block,
        title_spans: []const wiki.Span, is_heading: bool = true,
        title_depth: u8 = 0, title_list_path: []const u8 = "",
    };
    fn projected(a: A, entry: @import("blob_encoder").presentation_types.Entry) ![]const Section {
        const flat = try SerbianMeaningTest.projected(a, entry);
        const sections = try a.alloc(Section, flat.len);
        for (flat, sections) |old, *section| section.* = .{
            .title = old.title, .level = old.level, .blocks = old.blocks,
            .title_spans = if (old.blocks.len != 0 and old.blocks[0].kind == .heading) old.blocks[0].spans else &.{},
        };
        return sections;
    }
};

test "Aragonese decimal source addresses preserve standalone coalesced captions tables and complete Stored bodies" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator(); const encoder = @import("blob_encoder"); const T = encoder.presentation_types;
    const cases = .{
        .{ "chirman", @embedFile("testdata/an-decimal-noun/chirman-reader.json"), @as(?usize, null), @as(usize, 0), &[_]usize{3} },
        .{ "chirmana", @embedFile("testdata/an-decimal-noun/chirmana-reader.json"), @as(?usize, 1), @as(usize, 1), &[_]usize{2} },
        .{ "calso", @embedFile("testdata/an-decimal-noun/calso-reader.json"), @as(?usize, 3), @as(usize, 6), &[_]usize{ 3, 4, 6, 8, 10 } },
        .{ "badina", @embedFile("testdata/an-decimal-noun/badina-reader.json"), @as(?usize, 1), @as(usize, 3), &[_]usize{2} },
    };
    inline for (cases) |case| {
        const parsed = try std.json.parseFromSlice(struct { entries: []const T.Entry }, a, case[1], .{ .ignore_unknown_fields = true });
        try std.testing.expectEqual(@as(usize, 1), parsed.value.entries.len);
        const before = parsed.value.entries[0];
        try std.testing.expectEqualStrings("aragonés", before.language.?);
        try std.testing.expectEqualStrings("an", before.language_code);
        try std.testing.expectEqual(@as(usize, 0), before.organization.lexemes.len);
        var partitioned = before;
        const sections = try a.dupe(@TypeOf(before.sections[0]), before.sections);
        partitioned.sections = sections;
        if (case[2]) |split_block| {
            const old = before.sections[1].blocks;
            try std.testing.expectEqual(T.BlockKind.paragraph, old[split_block].kind);
            const blocks = try a.alloc(@TypeOf(old[0]), old.len + 1);
            @memcpy(blocks[0..split_block], old[0..split_block]);
            blocks[split_block] = old[split_block]; blocks[split_block].spans = old[split_block].spans[0..case[3]];
            blocks[split_block + 1] = old[split_block]; blocks[split_block + 1].spans = old[split_block].spans[case[3]..];
            @memcpy(blocks[split_block + 2 ..], old[split_block + 1 ..]);
            sections[1].blocks = blocks;
        }
        if (std.mem.eql(u8, case[0], "badina")) {
            try std.testing.expectEqual(@as(usize, 4), before.media.len);
            try std.testing.expectEqualStrings("badina", sections[1].blocks[1].spans[0].text);
            try std.testing.expect(sections[1].blocks[1].spans[0].bold);
            try std.testing.expectEqualStrings("una badina", sections[1].blocks[1].spans[2].text);
            try std.testing.expectEqualStrings("File:Not a Good Graving Day - Cedar Lawn Cemetery, Jackson MS.jpg", sections[1].blocks[1].spans[2].target);
            try std.testing.expect(std.mem.startsWith(u8, sections[1].blocks[2].spans[0].text, " 1. acumulación"));
        }
        const projected = try AragoneseDecimalTest.projected(a, partitioned);
        for (case[4], 0..) |block, ordinal| {
            const value = &@constCast(projected[1].blocks)[block];
            try std.testing.expectEqual(wiki.Kind.paragraph, value.kind);
            // The independently reviewed source/Reader addresses above are the
            // test's producer receipt; no paragraph-content inference in Layout.
            value.source_decimal_sense = true;
            value.text = try std.fmt.allocPrint(a, "{d}. ", .{ordinal + 1});
        }
        const actual = try buildForDictionary(a, projected, false, before.language, null, "anwiktionary");
        try std.testing.expectEqual(@as(usize, 1), actual.lexemes.len);
        try std.testing.expectEqualStrings("Noun", actual.lexemes[0].kind);
        try std.testing.expectEqual(@as(usize, 1), actual.lexemes[0].section);
        try std.testing.expectEqual(case[4].len, actual.lexemes[0].definitions.len);
        for (case[4], actual.lexemes[0].definitions) |block, sense| try std.testing.expectEqual(block, sense.block);
        const typed = try std.json.parseFromSlice(T.Layout, a, try std.json.Stringify.valueAlloc(a, actual, .{}), .{});
        partitioned.organization = typed.value;
        const encoded = try encoder.presentation_codec.encodeAlloc(a, .{ .entry = partitioned });
        const decoded = try encoder.presentation_codec.decodeAlloc(a, encoded, before.title, .language, .{ .heading = "aragonés", .code = "an" });
        try std.testing.expectEqualDeep(T.Stored{ .entry = partitioned }, decoded);
        try std.testing.expectEqualSlices(u8, encoded, try encoder.presentation_codec.encodeAlloc(a, decoded));
        // Rejoin the actual round-tripped split blocks; every other field,
        // action, style, example, table and media record must equal the original.
        var restored = decoded;
        restored.entry.organization = before.organization;
        if (case[2]) |split_block| {
            const decoded_sections = try a.dupe(@TypeOf(before.sections[0]), decoded.entry.sections);
            const old = decoded.entry.sections[1].blocks;
            const blocks = try a.alloc(@TypeOf(old[0]), old.len - 1);
            @memcpy(blocks[0..split_block], old[0..split_block]);
            blocks[split_block] = old[split_block];
            blocks[split_block].spans = try std.mem.concat(a, @TypeOf(old[split_block].spans[0]), &.{old[split_block].spans, old[split_block + 1].spans});
            @memcpy(blocks[split_block + 1 ..], old[split_block + 2 ..]);
            decoded_sections[1].blocks = blocks; restored.entry.sections = decoded_sections;
        }
        try std.testing.expectEqualDeep(T.Stored{ .entry = before }, restored);
        try std.testing.expectEqualSlices(u8, try encoder.presentation_codec.encodeAlloc(a, .{ .entry = before }), try encoder.presentation_codec.encodeAlloc(a, restored));
        for (@constCast(projected[1].blocks)) |*block| block.source_decimal_sense = false;
        const without_receipt = try buildForDictionary(a, projected, false, before.language, null, "anwiktionary");
        for (without_receipt.lexemes) |lexeme| try std.testing.expectEqual(@as(usize, 0), lexeme.definitions.len);
    }
}

test "Aragonese current badina decimal address preserves complete typed Figure flow and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator(); const encoder = @import("blob_encoder"); const T = encoder.presentation_types;
    const parsed = try std.json.parseFromSlice(struct { entries: []const T.Entry }, a,
        @embedFile("testdata/an-decimal-noun/badina-current-reader.json"), .{ .ignore_unknown_fields = true });
    try std.testing.expectEqual(@as(usize, 1), parsed.value.entries.len);
    const before = parsed.value.entries[0];
    try std.testing.expectEqualStrings("badina", before.title);
    try std.testing.expectEqualStrings("aragonés", before.language.?);
    try std.testing.expectEqualStrings("an", before.language_code);
    const original = before.sections[1].blocks[1];
    const original_flow = original.flow.?;
    try std.testing.expectEqual(@as(usize, 3), original_flow.len);
    try std.testing.expectEqualStrings("badina", original_flow[0].spans[0].text);
    try std.testing.expect(original_flow[0].spans[0].bold);
    const figure = original_flow[1].figure.?;
    try std.testing.expect(figure.content == .image);
    try std.testing.expectEqualStrings("Not a Good Graving Day - Cedar Lawn Cemetery, Jackson MS.jpg", figure.content.image.span.image.?.file);
    try std.testing.expectEqualStrings("una badina", figure.caption[0].text);
    try std.testing.expect(std.mem.startsWith(u8, original_flow[2].spans[0].text, " 1. acumulación"));
    try std.testing.expectEqualStrings("augua", original_flow[2].spans[1].target);
    try std.testing.expectEqualStrings("tierra", original_flow[2].spans[3].target);
    // Partition only the source-proved final physical decimal line. Retain the
    // complete independently compiled Figure and headword before its address.
    var partitioned = before;
    const sections = try a.dupe(@TypeOf(before.sections[0]), before.sections);
    partitioned.sections = sections;
    const old = before.sections[1].blocks;
    const blocks = try a.alloc(@TypeOf(original), old.len + 1);
    @memcpy(blocks[0..2], old);
    blocks[1].flow = original_flow[0..2];
    blocks[2] = original;
    blocks[2].flow = null;
    blocks[2].spans = original_flow[2].spans;
    sections[1].blocks = blocks;
    const projected = try AragoneseDecimalTest.projected(a, partitioned);
    const sense = &@constCast(projected[1].blocks)[2];
    sense.source_decimal_sense = true;
    sense.text = "1. ";
    const actual = try buildForDictionary(a, projected, false, before.language, null, "anwiktionary");
    try std.testing.expectEqual(@as(usize, 1), actual.lexemes.len);
    try std.testing.expectEqualStrings("Noun", actual.lexemes[0].kind);
    try std.testing.expectEqual(@as(usize, 1), actual.lexemes[0].definitions.len);
    try std.testing.expectEqual(@as(usize, 2), actual.lexemes[0].definitions[0].block);
    partitioned.organization = (try std.json.parseFromSlice(T.Layout, a,
        try std.json.Stringify.valueAlloc(a, actual, .{}), .{})).value;
    const encoded = try encoder.presentation_codec.encodeAlloc(a, .{ .entry = partitioned });
    const decoded = try encoder.presentation_codec.decodeAlloc(a, encoded, before.title, .language, .{ .heading = "aragonés", .code = "an" });
    try std.testing.expectEqualDeep(T.Stored{ .entry = partitioned }, decoded);
    // Rejoin from the decoded values, including the exact original inline-node
    // metadata, then compare every media/style/link/table/reference byte.
    var restored = decoded;
    const restored_sections = try a.dupe(@TypeOf(before.sections[0]), decoded.entry.sections);
    const restored_blocks = try a.dupe(@TypeOf(original), decoded.entry.sections[1].blocks[0..2]);
    const restored_flow = try a.alloc(@TypeOf(original_flow[0]), 3);
    @memcpy(restored_flow[0..2], restored_blocks[1].flow.?);
    restored_flow[2] = original_flow[2];
    restored_flow[2].spans = decoded.entry.sections[1].blocks[2].spans;
    restored_blocks[1].flow = restored_flow;
    restored_sections[1].blocks = restored_blocks;
    restored.entry.sections = restored_sections;
    restored.entry.organization = before.organization;
    try std.testing.expectEqualDeep(T.Stored{ .entry = before }, restored);
    try std.testing.expectEqualSlices(u8, try encoder.presentation_codec.encodeAlloc(a, .{ .entry = before }),
        try encoder.presentation_codec.encodeAlloc(a, restored));
    sense.source_decimal_sense = false;
    const no_receipt = try buildForDictionary(a, projected, false, before.language, null, "anwiktionary");
    for (no_receipt.lexemes) |lexeme| try std.testing.expectEqual(@as(usize, 0), lexeme.definitions.len);
}

test "Malayalam Japanese noun in to keeps the two authored senses and complete Reader body" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const encoder = @import("blob_encoder");
    const T = encoder.presentation_types;
    const saved = try std.json.parseFromSlice(struct { entries: []const T.Entry }, a,
        @embedFile("testdata/ml-noun/to-ja-reader.json"), .{ .ignore_unknown_fields = true });
    try std.testing.expectEqual(@as(usize, 1), saved.value.entries.len);
    const before = saved.value.entries[0];
    try std.testing.expectEqualStrings("to", before.title);
    try std.testing.expectEqualStrings("ja", before.language_code);
    const sections = try AragoneseDecimalTest.projected(a, before);
    const owner = before.language.?;
    const layout = try buildForEntryWithClassifiedCode(a, sections, false, owner, "ja", null, "mlwiktionary", &.{}, before.title);
    try std.testing.expectEqual(before.organization.lexemes.len + 1, layout.lexemes.len);
    const noun = layout.lexemes[1];
    try std.testing.expectEqualStrings("Noun", noun.kind);
    try std.testing.expectEqualStrings(owner, noun.language);
    try std.testing.expectEqual(@as(usize, 2), noun.section);
    try std.testing.expectEqual(@as(usize, 2), noun.definitions.len);
    try std.testing.expectEqual(@as(usize, 1), noun.definitions[0].block);
    try std.testing.expectEqual(@as(usize, 2), noun.definitions[1].block);
    var entry = before;
    entry.organization = (try std.json.parseFromSlice(T.Layout, a, try std.json.Stringify.valueAlloc(a, layout, .{}), .{})).value;
    try std.testing.expectEqualDeep(before.organization.lexemes[0], entry.organization.lexemes[0]);
    try std.testing.expectEqualDeep(before.organization.lexemes[1], entry.organization.lexemes[2]);
    try std.testing.expectEqualSlices(usize, &.{ 0, 2, 3, 6, 7 }, before.organization.other_sections);
    try std.testing.expectEqualSlices(usize, &.{ 0, 3, 6, 7 }, entry.organization.other_sections);
    const encoded = try encoder.presentation_codec.encodeAlloc(a, .{ .entry = entry });
    var decoded = try encoder.presentation_codec.decodeAlloc(a, encoded, before.title, .language, .{ .heading = owner, .code = "ja" });
    try std.testing.expectEqualDeep(T.Stored{ .entry = entry }, decoded);
    try std.testing.expectEqualSlices(u8, encoded, try encoder.presentation_codec.encodeAlloc(a, decoded));
    // Page 8599, revision 534593. Each Japanese target and its Malayalam gloss
    // still points at the original linked text in the unchanged body.
    const blocks = decoded.entry.sections[noun.section].blocks;
    for ([_][2][]const u8{ .{ "戸#Japanese", "വാതിൽ" }, .{ "都#Japanese", "മെട്രോപ്പൊളിസ്" } }, noun.definitions) |targets, sense| {
        const spans = blocks[sense.block].spans;
        try std.testing.expectEqualStrings(targets[0], spans[0].target);
        try std.testing.expectEqualStrings(targets[1], spans[2].target);
    }
    decoded.entry.organization = before.organization;
    try std.testing.expectEqualDeep(T.Stored{ .entry = before }, decoded);

    const Section = AragoneseDecimalTest.Section;
    var probe = [_]Section{ sections[0], sections[2] };
    try std.testing.expect(classifiedNounSection(&probe, 1, owner, "നാമം"));
    probe[0] = sections[3]; // The later unresolved Lojban heading cannot borrow Japanese ownership.
    try std.testing.expect(!classifiedNounSection(&probe, 1, owner, "നാമം"));
    probe[0] = sections[0];
    probe[1].title_depth = 1;
    try std.testing.expect(!classifiedNounSection(&probe, 1, owner, "നാമം"));
    probe[1] = sections[2];
    probe[1].blocks = &.{};
    try std.testing.expect(!classifiedNounSection(&probe, 1, owner, "നാമം"));
    probe[1] = sections[2];
    probe[1].title = "നാമവിശേഷണം";
    try std.testing.expect(!classifiedNounSection(&probe, 1, owner, "നാമം"));
    probe[1] = sections[2];
    try std.testing.expectEqual(@as(usize, 0), (try buildForEntryWithClassifiedCode(a, &probe, false, owner, "ja", null, "enwiktionary", &.{}, "to")).lexemes.len);
}

test "Amharic edition keeps the Nng noun sense separate from its numbered citation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const encoder = @import("blob_encoder");
    const T = encoder.presentation_types;
    const Section = struct { title: []const u8, level: u8, is_heading: bool = true, blocks: []const wiki.Block };
    const title = "ǀeeki";
    const url = "https://open.uct.ac.za/server/api/core/bitstreams/eff77f15-54d4-4053-a2b2-f65e91cb9256/content";
    const label = "Ouma Geelmeind ke kxʼu ǁxaǁxa Nǀuu";
    var renderer: wiki.Renderer = .{ .a = a, .context = .{ .title = title } };
    // Amharic Wiktionary page 5032, revision 21605. Both sections use '#'.
    const sections = [_]Section{
        .{ .title = "Nǁng", .level = 2, .blocks = &.{} },
        .{ .title = "ስም", .level = 3, .blocks = try renderer.renderBody("#[[woman]]") },
        .{ .title = "references", .level = 3, .blocks = try renderer.renderBody("#Ouma Geelmeid “[" ++ url ++ " " ++ label ++ "]” Centre for African Language Diversity (2016)") },
    };
    const layout = try buildForDictionary(a, &sections, false, "Nǁng", null, "amwiktionary");
    const encoded = try encoder.presentation_codec.encodeBuildAlloc(a, @as([]const wiki.Span, &.{}), &sections,
        layout, @as([]const T.Reference, &.{}), @as([]const T.Media, &.{}));
    const doc = try encoder.presentation_codec.decodeAlloc(a, encoded, title, .language, .{ .heading = "Nǁng", .code = "ngh" });
    try std.testing.expectEqualSlices(u8, encoded, try encoder.presentation_codec.encodeAlloc(a, doc));
    try std.testing.expectEqual(@as(usize, 1), doc.entry.organization.lexemes.len);
    const noun = doc.entry.organization.lexemes[0];
    try std.testing.expectEqualStrings("Noun", noun.kind);
    try std.testing.expectEqualStrings("Nǁng", noun.language);
    try std.testing.expectEqual(@as(usize, 1), noun.section);
    try std.testing.expectEqual(@as(usize, 1), noun.definitions.len);
    const gloss = doc.entry.sections[noun.section].blocks[noun.definitions[0].block];
    try std.testing.expectEqual(.link, gloss.spans[0].kind);
    try std.testing.expectEqualStrings("woman", gloss.spans[0].target);
    try std.testing.expectEqualStrings("woman", gloss.spans[0].text);
    try std.testing.expectEqualSlices(usize, &.{ 0, 2 }, doc.entry.organization.other_sections);
    const citation = doc.entry.sections[2].blocks[0].spans;
    try std.testing.expectEqual(@as(usize, 3), citation.len);
    try std.testing.expectEqual(.external_link, citation[1].kind);
    try std.testing.expectEqualStrings(url, citation[1].target);
    try std.testing.expectEqualStrings(label, citation[1].text);
    try std.testing.expectEqual(@as(usize, 0), (try buildForDictionary(a, &sections, false, "Nǁng", null, "enwiktionary")).lexemes.len);
    try std.testing.expectEqual(@as(usize, 0), (try buildForDictionary(a, &sections, true, null, null, "amwiktionary")).lexemes.len);
    var other = sections[1];
    other.level = 2;
    try std.testing.expect(!dictionaryNounSection(other, "Nǁng", "amwiktionary"));
    other.level = 3;
    other.is_heading = false;
    try std.testing.expect(!dictionaryNounSection(other, "Nǁng", "amwiktionary"));
}

test "TR foreign Ad noun requires classified code and matching parsed headword in its own dictionary" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var renderer: wiki.Renderer = .{ .a = a, .context = .{} };
    const body = try renderer.renderBody("<strong class=\"Cyrl headword\" lang=\"ady\">лӏэныгъ</strong>\n# [[ölüm]]\n");
    const Section = struct {
        title: []const u8, level: u8, blocks: []const wiki.Block = &.{},
        is_heading: bool = true, title_depth: u8 = 0, title_list_path: []const u8 = "",
        title_spans: []const wiki.Span = &.{},
    };
    const noun: Section = .{ .title = "Ad", .level = 3, .blocks = body, .title_spans = &.{.{ .text = "Ad" }} };
    const sections = [_]Section{ .{ .title = "Adigece", .level = 2 }, noun };
    try std.testing.expectEqualStrings("Noun", ownedTurkishForeignNounPart(noun, "Adigece", "ady", "trwiktionary") orelse return error.TestUnexpectedResult);
    try std.testing.expectEqual(@as(usize, 1), (try buildForEntryWithClassifiedCode(a, &sections, false, "Adigece", "ady", null, "trwiktionary", &.{}, null)).lexemes.len);
    try std.testing.expectEqual(@as(usize, 0), (try buildForDictionary(a, &sections, false, "Adigece", null, "trwiktionary")).lexemes.len);
    try std.testing.expectEqual(@as(usize, 0), (try buildForEntryWithClassifiedCode(a, &sections, true, "Adigece", "ady", null, "trwiktionary", &.{}, null)).lexemes.len);
    for ([_][]const u8{ "", "en", "tr", "ady-Latn", "ady2" }) |code|
        try std.testing.expect(ownedTurkishForeignNounPart(noun, "Adigece", code, "trwiktionary") == null);
    for ([_]?[]const u8{ null, "", "Unclassified" }) |owner|
        try std.testing.expect(ownedTurkishForeignNounPart(noun, owner, "ady", "trwiktionary") == null);
    for ([_][]const u8{ "", "enwiktionary", "adywiktionary", "trwiktionary2" }) |wiki_id|
        try std.testing.expect(ownedTurkishForeignNounPart(noun, "Adigece", "ady", wiki_id) == null);
    for (0..10) |case| {
        var changed = noun;
        const blocks = try a.dupe(wiki.Block, body); changed.blocks = blocks;
        const head = try a.dupe(wiki.Span, blocks[0].spans); blocks[0].spans = head;
        var heading = [_]wiki.Span{.{ .text = "Ad" }}; changed.title_spans = &heading;
        switch (case) {
            0 => head[0].language = "tr",
            1 => head[0].role = .normal,
            2 => head[0].flags.bold = false,
            3 => head[0].provenance = .protected_literal,
            4 => head[0].generated_diagnostic = true,
            5 => blocks[1].kind = .paragraph,
            6 => changed.level = 4,
            7 => changed.title = "ad",
            8 => heading[0].provenance = .protected_literal,
            9 => changed.title_list_path = "*",
            else => unreachable,
        }
        try std.testing.expect(ownedTurkishForeignNounPart(changed, "Adigece", "ady", "trwiktionary") == null);
    }
    // The classified code, not a translated UI label, is compared to the headword.
    try std.testing.expectEqualStrings("Noun", ownedTurkishForeignNounPart(noun, "Independent registered heading", "ady", "trwiktionary") orelse return error.TestUnexpectedResult);
    try std.testing.expect(partOfSpeech("Ad") == null);
}

test "TR complete foreign noun and German missing translation records retain all bodies actions notices and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const encoder = @import("blob_encoder"); const types = encoder.presentation_types;
    const Section = struct {
        title: []const u8, level: u8, blocks: []const wiki.Block,
        is_heading: bool = true, title_depth: u8 = 0, title_list_path: []const u8 = "",
        title_spans: []const wiki.Span = &.{},
    };
    const cases = .{
        .{ @embedFile("testdata/tr-foreign-noun01/ady-reader.json"), "fe7d5fc0f54a3e4a27b14ff5259be81cf5182aea302fe985800dba05b0ac373b", "лӏэныгъ", "Adigece", "ady" },
        .{ @embedFile("testdata/tr-foreign-noun01/de-notice-reader.json"), "6433c9580db7ad4c1ca90bf8d21925a6608b365c6a90abb4930b56a99e6ce88d", "-jährig", "Almanca", "de" },
    };
    inline for (cases, 0..) |case, case_index| {
        const fixture = case[0]; var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(fixture, &digest, .{});
        try std.testing.expectEqualStrings(case[1], &std.fmt.bytesToHex(digest, .lower));
        const parsed = try std.json.parseFromSlice(struct { entries: []const types.Entry }, a, fixture, .{ .ignore_unknown_fields = true });
        try std.testing.expectEqual(@as(usize, 1), parsed.value.entries.len);
        const before = parsed.value.entries[0];
        try std.testing.expectEqualStrings(case[2], before.title);
        try std.testing.expectEqualStrings(case[3], before.language orelse return error.TestUnexpectedResult);
        try std.testing.expectEqualStrings(case[4], before.language_code);
        try std.testing.expectEqual(@as(usize, 0), before.organization.lexemes.len);
        const projected = try std.json.parseFromSlice(struct { entries: []const struct { sections: []const Section } }, a, fixture, .{ .ignore_unknown_fields = true });
        const sections = try a.dupe(Section, projected.value.entries[0].sections);
        // Only a build-time regression projection. The retained Reader is not
        // an expansion capture and does not itself carry parser provenance.
        for (sections, before.sections) |*section, typed_section| {
            section.title_spans = try a.dupe(wiki.Span, &.{.{ .text = section.title }});
            const blocks = try a.dupe(wiki.Block, section.blocks); section.blocks = blocks;
            for (blocks, typed_section.blocks) |*block, typed_block| {
                const spans = try a.dupe(wiki.Span, block.spans); block.spans = spans;
                for (spans, typed_block.spans) |*span, typed_span| span.flags = .{
                    .bold = typed_span.bold, .italic = typed_span.italic, .code = typed_span.code,
                    .small = typed_span.small, .superscript = typed_span.superscript, .subscript = typed_span.subscript,
                    .strike = typed_span.strike, .underline = typed_span.underline,
                };
            }
        }
        const layout = try buildForEntryWithClassifiedCode(a, sections, false, before.language, before.language_code, null, "trwiktionary", &.{}, before.title);
        const expected_layout: types.Layout = if (case_index == 0) .{
            .lexemes = &.{.{ .language = "Adigece", .kind = "Noun", .section = 3,
                .definitions = &.{.{ .block = 1 }}, .introduction = &.{0}, .related_sections = &.{4} }},
            .other_sections = &.{ 0, 1, 2 },
        } else before.organization;
        const typed = try std.json.parseFromSlice(types.Layout, a, try std.json.Stringify.valueAlloc(a, layout, .{}), .{});
        try std.testing.expectEqualDeep(expected_layout, typed.value);
        if (case_index == 0) {
            const sense = before.sections[3].blocks[1];
            try std.testing.expect(sense.kind == .definition and sense.spans.len == 1);
            try std.testing.expect(sense.spans[0].kind == .link);
            try std.testing.expectEqualStrings("ölüm", sense.spans[0].text);
            try std.testing.expectEqualStrings("ölüm", sense.spans[0].target);
            try std.testing.expectEqualStrings("ady", before.sections[3].blocks[0].spans[0].language);
        } else {
            try std.testing.expect(std.mem.indexOf(u8, fixture, "Bu tanımın Türkçe çevirisi") != null);
        }
        var expected: types.Stored = .{ .entry = before }; expected.entry.organization = expected_layout;
        const bytes = try encoder.presentation_codec.encodeAlloc(a, expected);
        const decoded = try encoder.presentation_codec.decodeAlloc(a, bytes, before.title, .language, .{ .heading = before.language.?, .code = before.language_code });
        try std.testing.expectEqualDeep(expected, decoded);
        try std.testing.expectEqualSlices(u8, bytes, try encoder.presentation_codec.encodeAlloc(a, decoded));
        var restored = decoded; restored.entry.organization = before.organization;
        try std.testing.expectEqualDeep(types.Stored{ .entry = before }, restored);
    }
}

